"""Create an offline search viewer for a separately built reference database."""
import argparse
import json
from pathlib import Path
import sqlite3

HTML = '''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SignBridge · 手语参照数据库</title><link rel="stylesheet" href="review.css"><body><main><h1>手语参照数据库</h1><p id="summary"></p><aside>CE-CSL原标签与教程扩展分别保留。文字相同只表示标签重合，不证明动作、词界或国家通用手语规范相同。默认CE词条和录像只检索原train集合，教程另列；本轮未训练模型、未重建5988段骨骼。</aside><nav><a href="README.md">使用说明</a><a href="database.sqlite" download>SQLite数据库</a><a href="report.json">统计与边界</a><a href="ce-csl/label/train.csv">CE格式train标签</a><a href="candidates/label/candidates.csv">教程候选标签</a><a href="reviews/index.html">“你”的用户确认与原展示</a></nav><section class="controls"><label>字词或中文句子<input id="query" placeholder="例如：我、你、上午、考试1" autocomplete="off"></label><label>CE-CSL来源集合<select id="split"><option value="train">train</option><option value="dev">dev</option><option value="test">test</option><option value="all">全部（审阅用）</option></select></label><label>词表范围<select id="kind"><option value="all">全部索引</option><option value="ce">CE-CSL标签</option><option value="new">CE-CSL无相同标签的扩展</option><option value="tutorial">全部教程参考</option></select></label><button id="search">检索</button></section><p id="count" role="status"></p><section><h2>词条索引</h2><div id="terms" class="terms"></div><button id="more">再显示50条</button></section><section><h2>CE-CSL来源句子</h2><p id="sample-note"></p><div id="samples"></div><button id="sample-more">再显示20段</button></section><section><h2>教程参考与数据库缺项</h2><p>教学范围不是核准词级起止。同词多源示范分别保留；未决项目不被当成正确标签。</p><div id="tutorials"></div><button id="tutorial-more">再显示20条</button></section><section><h2>基础候选片段</h2><p>28段、3538帧，单独candidates集合，不混入原train/dev/test；“你”使用60帧保守修订窗口。用户确认的是当前展示表达，不自动确认每段词界、镜像或连续稳定性。</p><div id="candidates"></div></section><section><h2>新增两批教程原片</h2><p>来自目录1与2/shouyu；课程文件名仅作显示标题，未当作中文句子或Gloss。没有可靠标注的字段留空，原课在reference集合单独保存。</p><div id="additional-sources"></div></section><section><h2>附加字幕候选</h2><p id="additional-note"></p><p>以下复用已保存的片段和源SHA，不是新人工批准词条；字幕窗口不是核准词界，不并入CE train/dev/test。</p><div id="additional-candidates"></div><button id="additional-more">再显示20段</button></section><section><h2>隔离与去重</h2><div id="conflicts"></div><p>字节相同只存一份新库视频数据；相同词句的不同录像保留。14个教程重复文件只保留别名映射，源文件未删除。</p></section></main><script src="review-data.js"></script><script src="review.js"></script></body></html>'''

CSS = '''*{box-sizing:border-box}body{margin:0;background:#f3f5ef;color:#1e3931;font:16px/1.65 system-ui,sans-serif}main{max-width:1160px;margin:auto;padding:28px}h1{font-size:34px;line-height:1.25}h2{font-size:22px}aside{padding:18px;border-left:5px solid #967431;background:#fff1d1}nav{display:flex;flex-wrap:wrap;gap:16px;margin:22px 0}a{color:#17677a;overflow-wrap:anywhere}.controls{display:flex;gap:16px;flex-wrap:wrap;align-items:end}label{display:grid;gap:6px}label:first-child{flex:1;min-width:200px}input,select,button{font:inherit;border:1px solid #91ab9f;border-radius:7px;padding:9px;background:#fff;color:inherit}button{cursor:pointer}section{padding:20px;margin:24px 0;background:#fff;border-radius:12px}article{padding:15px 0;border-bottom:1px solid #d7e1d7}article h3{margin:0 0 5px;font-size:18px}article p{margin:5px 0}.terms{display:flex;gap:8px;flex-wrap:wrap}.term{background:#e6eee2}.warning{background:#fff2df;padding:10px;border-left:4px solid #a8792b}small{color:#53675d}video{display:block;width:min(100%,720px);max-height:620px;margin:14px 0;background:#222}button:focus-visible,a:focus-visible{outline:3px solid #b27315}#more,#sample-more,#tutorial-more{margin-top:15px}[hidden]{display:none!important}@media(max-width:550px){main{padding:16px}h1{font-size:29px}section{padding:16px}.controls>*{width:100%}}'''

JS = '''const data=window.SIGNBRIDGE_REFERENCE;const $=s=>document.querySelector(s);let termLimit=50,sampleLimit=20,tutorialLimit=20,additionalLimit=20,selected=null;const matches=new Map(data.occurrences.map(x=>[x.term_id,x.sample_ids]));function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}function video(button,path,container,start){button.addEventListener('click',()=>{let player=container.querySelector('video');if(player){player.remove();button.textContent='打开视频';return}document.querySelectorAll('video').forEach(v=>v.remove());player=el('video');player.controls=true;player.preload='metadata';player.playsInline=true;player.src=path;if(start!==undefined)player.addEventListener('loadedmetadata',()=>{player.currentTime=start},{once:true});container.append(player);button.textContent='收起视频';player.addEventListener('error',()=>container.append(el('p','视频读取失败，请核对本机文件。','warning')),{once:true});});}function sampleCard(row,parent,annotation){const a=el('article');a.dataset.id=row.id;a.append(el('h3',row.raw['Chinese Sentences']),el('p',row.raw.Gloss),el('small',`${row.raw.Number} · ${row.source_split} · ${annotation}`));const b=el('button','打开视频');a.append(el('br'),b);video(b,row.local_video,a);parent.append(a)}function update(){const q=$('#query').value.trim(),split=$('#split').value,kind=$('#kind').value;const qn=q.toLowerCase();const list=data.terms.filter(t=>(!t.in_ce_csl||split==='all'||t.ce_occurrences_by_split[split]>0)&&(!q||t.label.toLowerCase().includes(qn))&&(!selected||t.id===selected)&& (kind==='all'||kind==='ce'&&t.in_ce_csl||kind==='new'&&t.new_label_candidate||kind==='tutorial'&&t.tutorial_lexical_ids.length));$('#terms').replaceChildren();for(const t of list.slice(0,termLimit)){const b=el('button',`${t.label} · ${t.in_ce_csl?'CE标签':'教程'+t.unit_type}`,'term');b.dataset.term=t.id;b.addEventListener('click',()=>{selected=t.id;sampleLimit=20;tutorialLimit=20;additionalLimit=20;update()});$('#terms').append(b)}$('#more').hidden=list.length<=termLimit;$('#count').textContent=`匹配 ${list.length} 个索引条目；标签匹配不等于同一动作。`;let ids=null;if(selected)ids=new Set(matches.get(selected)||[]);const sr=data.samples.filter(s=>s.dataset_id==='CE-CSL'&&s.status==='retained'&&(split==='all'||s.source_split===split)&&(ids?ids.has(s.id):!q||s.raw['Chinese Sentences'].includes(q)||s.raw.Gloss.includes(q)));$('#samples').replaceChildren();for(const s of sr.slice(0,sampleLimit))sampleCard(s,$('#samples'),'来源整段标签，词级边界未对齐');$('#sample-note').textContent=`${split} 集合：${sr.length} 段；显示 ${Math.min(sr.length,sampleLimit)} 段。dev/test仅供审阅，不并入训练。`;$('#sample-more').hidden=sr.length<=sampleLimit;const tr=data.tutorials.filter(t=>(!q||t.canonical_text.toLowerCase().includes(qn)||t.meaning.includes(q))&&(!selected||t.term_id===selected)&&(kind==='all'||kind==='tutorial'||kind==='new'&&t.relation==='not_in_ce_csl_exact_labels'||kind==='ce'&&t.label_present_in_ce_csl));$('#tutorials').replaceChildren();for(const t of tr.slice(0,tutorialLimit)){const a=el('article');a.dataset.id=t.id;a.append(el('h3',`${t.canonical_text} · ${t.unit_type}`),el('p',t.meaning),el('p',t.manual_form_note||''),el('small',`审计序号${t.lesson_number} · ${t.relation} · ${t.evidence_status}`));if(t.evidence_status==='unresolved')a.append(el('p','此来源留疑，未自动核准。','warning'));const start=t.source_intervals[0].start;const b=el('button',`打开原课 ${start}秒`);a.append(el('br'),b);video(b,`tutorial-sources/video/${t.source_id}.mp4`,a,start);$('#tutorials').append(a)}$('#tutorial-more').hidden=tr.length<=tutorialLimit;$('#candidates').replaceChildren();for(const s of data.samples.filter(s=>s.dataset_id==='tutorial-basic-candidates'&&(!q||s.raw['Chinese Sentences'].includes(q))))sampleCard(s,$('#candidates'),'助手候选，不是CE官方标注或已核准独立动作');$('#additional-sources').replaceChildren();for(const s of data.samples.filter(s=>s.dataset_id==='additional-course-sources'&&(!q||s.display_title_not_label.includes(q)))){const a=el('article');a.dataset.id=s.id;a.append(el('h3',s.display_title_not_label),el('p',`${s.source_folder} · 整课reference · 中文/Gloss未强填`));const b=el('button','打开原课');a.append(b);video(b,s.local_video,a);$('#additional-sources').append(a)}const extra=data.samples.filter(s=>s.dataset_id==='additional-caption-candidates'&&(!q||s.raw['Chinese Sentences'].includes(q)));$('#additional-candidates').replaceChildren();for(const s of extra.slice(0,additionalLimit))sampleCard(s,$('#additional-candidates'),'来源字幕候选，词义/词界/动作未核准');$('#additional-note').textContent=`匹配${extra.length}段字幕候选；显示${Math.min(extra.length,additionalLimit)}段。`;$('#additional-more').hidden=extra.length<=additionalLimit;}$('#summary').textContent=`${data.report.retained_ce_samples}条CE-CSL主集录像 · ${data.report.ce_gloss_labels}个来源Gloss标签 · ${data.report.tutorial_lexical_records}条教程义项 · ${data.report.tutorial_new_exact_label_typed_entries}个新增类型化标签候选`;
function reset(){selected=null;termLimit=50;sampleLimit=20;tutorialLimit=20;additionalLimit=20;update()}$('#query').addEventListener('input',reset);$('#split').addEventListener('change',reset);$('#kind').addEventListener('change',reset);$('#search').addEventListener('click',reset);$('#more').addEventListener('click',()=>{termLimit+=50;update()});$('#sample-more').addEventListener('click',()=>{sampleLimit+=20;update()});$('#tutorial-more').addEventListener('click',()=>{tutorialLimit+=20;update()});$('#additional-more').addEventListener('click',()=>{additionalLimit+=20;update()});for(const c of data.conflicts){const a=el('article');a.append(el('h3','同视频不同标签：已隔离'),el('p',c.source_rows.map(x=>x.Number+'：'+x['Chinese Sentences']).join('；')),el('small','保留原标注，不猜哪条正确，不进入主训练导出。'));$('#conflicts').append(a)}update();document.addEventListener('visibilitychange',()=>{if(document.hidden)document.querySelectorAll('video').forEach(v=>v.pause())});'''


def build(root):
    root = Path(root).resolve()
    if (root / 'index.html').exists():
        raise FileExistsError('Review already exists; choose a new staged database output')
    con = sqlite3.connect(f'file:{root}/database.sqlite?mode=ro', uri=True)
    try:
        values = lambda table: [json.loads(r[0]) for r in con.execute('SELECT record_json FROM ' + table)]
        terms, samples = values('terms'), values('samples')
        mapping = {r['lexical_id']: r for r in [json.loads(x) for x in (root / 'tutorial/ce-csl-comparison.jsonl').read_text().splitlines()]}
        tutorials = [{**r, **mapping[r['id']]} for r in values('lexical_evidence')]
        occurrences = []
        for (tid,) in con.execute('SELECT id FROM terms'):
            ids = [r[0] for r in con.execute('SELECT DISTINCT sample_id FROM occurrences WHERE term_id=?', (tid,))]
            if ids:
                occurrences.append({'term_id': tid, 'sample_ids': ids})
        data = {'terms': terms, 'samples': samples, 'tutorials': tutorials, 'occurrences': occurrences,
                'conflicts': values('conflicts'), 'report': json.loads((root / 'report.json').read_text())}
    finally:
        con.close()
    for name, text in [('index.html', HTML), ('review.css', CSS), ('review.js', JS),
                       ('review-data.js', 'window.SIGNBRIDGE_REFERENCE=' + json.dumps(data, ensure_ascii=False, separators=(',', ':')).replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026') + ';\n')]:
        (root / name).write_text(text)
    # Original HTML remains byte evidence; this separate page uses working local relative media paths.
    (root/'reviews/index.html').write_text('<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>你 · 用户确认记录</title><style>body{font:17px/1.7 system-ui;max-width:1000px;margin:auto;padding:24px;color:#203b32;background:#f5f6f0}img,video{max-width:100%}video{display:block;width:720px}aside{padding:16px;background:#fff0ce}</style><h1>“你”的用户确认</h1><p>用户原话：我已看过，“你”现在的动作是对的。</p><aside>确认绑定此前展示的当前表达与校准候选。以下保留对照证据，不把原生基线、所有连续帧、词界或新派生动作自动批准。</aside><p><a href="basic-you-user-review.json">用户确认与文件SHA</a> · <a href="displayed/index.html">原展示HTML字节证据（归档副本，非此目录可用播放器）</a> · <a href="../index.html">返回数据库</a></p><h2>原片／基线／校准关键帧对照</h2><img src="displayed/basic-you-corrected-hand-compare.jpg" alt="此前你关键帧的原片基线与校准对照"><h2>原生旧窗口对照，末尾含下一词转换</h2><video controls preload="metadata" src="displayed/basic-you-original-native.mp4"></video><h2>保守60帧原片窗口，词界仍为助手修订</h2><video controls preload="metadata" src="displayed/basic-you-boundary-fixed-source.mp4"></video>\n')
    return {'page': str(root / 'index.html'), 'terms': len(terms), 'samples': len(samples), 'tutorials': len(tutorials)}


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--database', type=Path, required=True)
    print(json.dumps(build(parser.parse_args().database)))
